    const eventFunc = (event) => ({ Player }) => {
        if (CurrentScreen !== 'ChatRoom')
            return;
        InvokeResponse({ triggerType: 'orgasm', type: event }, Player);
    };
    function init() {
        X.on('PlayerJoin', (player) => InvokeResponse({ triggerType: 'event', type: 'Join' }, player));
        X.on('PlayerLeave', (player) => InvokeResponse({ triggerType: 'event', type: 'Leave' }, player));
        k.on('orgasmed', eventFunc('Orgasmed'));
        k.on('ruined', eventFunc('Ruined'));
        k.on('resisted', eventFunc('Resisted'));
        B.on('Activity', (data, sender, message, metadata) => {
            if (metadata?.TargetCharacter?.MemberNumber !== Player.MemberNumber)
                return;
            if (!metadata?.ActivityName || !metadata?.GroupName || !sender.MemberNumber)
                return;
            InvokeResponse({
                triggerType: 'activity',
                activity: metadata.ActivityName,
                bodypart: metadata.GroupName,
                from: sender.MemberNumber,
                arousal: sender.ArousalSettings?.Progress || 0,
            }, Player, sender);
        });
    }

